insert into public.lesson_items (lesson_id, idx, kind, en, ar_meaning, translit, example_en, example_ar) values ('step-grammar-passive',0,'pattern','is/are + past participle','المضارع المبني للمجهول','ايز / ار + باست بارتيسيبل','English is spoken here.','الانجليزي يتكلمونه هنا.');
